const byId = {}, gInfo = {};
CAT.groups.forEach(g => (gInfo[g.id] = g));
CAT.badges.forEach(b => (byId[b.id] = b));

const HEAD = {
  'content-type': 'application/json; charset=utf-8',
  'access-control-allow-origin': '*',
  'cache-control': 'public, max-age=3600',
};
const fail = (msg, status = 400) =>
  new Response(JSON.stringify({ error: msg }), { status, headers: { ...HEAD, 'cache-control': 'no-store' } });

// code "m<style>-<hex>": a selection in the default order, one style.
function fromMask(code) {
  const m = /^m(\d+)-([0-9a-f]+)$/i.exec(code);
  if (!m || !STYLES[+m[1]]) return null;
  const items = [];
  for (let k = 0; k < m[2].length; k++) {
    const v = parseInt(m[2][k], 16);
    for (let j = 0; j < 4; j++) {
      const b = CAT.badges[k * 4 + j];
      if (v >> j & 1 && b) items.push({ b, style: +m[1] });
    }
  }
  // default order: group order, then catalog order inside the group
  const rank = {};
  CAT.groups.forEach((g, i) => (rank[g.id] = i));
  items.sort((a, b) => rank[a.b.g] - rank[b.b.g] || CAT.badges.indexOf(a.b) - CAT.badges.indexOf(b.b));
  return items;
}

// code "o<base64url>": deflated list of numbers. First is the style, then one per badge, in order:
// catalogIndex * 32 + (0 for the pack style, or the style number + 1 for a single badge).
async function fromList(code) {
  if (code[0] !== 'o') return null;
  const s = code.slice(1).replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(s + '='.repeat((4 - (s.length % 4)) % 4));
  const bytes = Uint8Array.from(bin, c => c.charCodeAt(0));
  const ds = new DecompressionStream('deflate-raw');
  const w = ds.writable.getWriter(); w.write(bytes).catch(() => {}); w.close().catch(() => {});
  const raw = new Uint8Array(await new Response(ds.readable).arrayBuffer());
  const nums = []; let v = 0, sh = 0;
  for (const x of raw) { v |= (x & 127) << sh; if (x & 128) sh += 7; else { nums.push(v); v = 0; sh = 0; } }
  const base = nums.shift();
  if (!STYLES[base]) return null;
  const items = [];
  for (const n of nums) {
    const b = CAT.badges[Math.floor(n / 32)], o = n % 32;
    if (!b) continue;
    items.push({ b, style: o ? o - 1 : base });
  }
  return items;
}

function manifest(items) {
  const groups = [];
  items.forEach(({ b }) => { if (!groups.includes(b.g)) groups.push(b.g); });
  return {
    filters: items.map(({ b, style }) => ({
      id: b.id, groupId: b.g, name: b.n, pattern: b.p,
      imageURL: RAW + STYLES[style] + '/' + b.f,
      tagColor: '#00000000', borderColor: '#00000000', textColor: '#00000000',
      tagStyle: 'filled and bordered', isEnabled: true, type: 'filter',
    })),
    groups: groups.map(id => ({
      id, name: gInfo[id].name, color: gInfo[id].color,
      borderColor: gInfo[id].border || gInfo[id].color, isExpanded: true,
    })),
  };
}

export default {
  async fetch(req) {
    if (req.method === 'OPTIONS') return new Response(null, { headers: HEAD });
    const url = new URL(req.url);
    const m = /^\/p\/([A-Za-z0-9_-]+)(?:\.json)?$/.exec(url.pathname);
    if (!m) return new Response('FR Badges pack links. Make one at https://farizmohd70.github.io/FR-Badges/make.html', { headers: { 'content-type': 'text/plain; charset=utf-8' } });
    try {
      await loadStyles();
      const items = fromMask(m[1]) || (await fromList(m[1]));
      if (!items) return fail('This pack link is not valid.');
      if (!items.length) return fail('This pack has no badges.');
      return new Response(JSON.stringify(manifest(items)), { headers: HEAD });
    } catch (e) {
      return fail('This pack link is not valid.');
    }
  },
};
